1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * Rejects a create request whose required owner fields are missing or blank. Runs
13	 * first in the {@code POST /api/owners} pipeline so an incomplete body is a 400
14	 * before any owner is built or saved. It binds the body once and republishes it as
15	 * a variable for the later {@link BuildOwner} step.
16	 *
17	 * <p>The address is normalized in place first (see {@link AddressNormalizer}) so the
18	 * required-field check rejects an address that is blank once normalized, and every
19	 * later step — including the household comparisons and the stored, returned value —
20	 * sees the canonical form.
21	 */
22	public class ValidateOwnerFields {
23	
24	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
25	            throws MissingOwnerFieldsException {
26	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
27	        List<String> missing = new ArrayList<>();
28	        require(missing, "firstName", request.getFirstName());
29	        require(missing, "lastName", request.getLastName());
30	        require(missing, "address", request.getAddress());
31	        require(missing, "city", request.getCity());
32	        require(missing, "telephone", request.getTelephone());
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        validated.set(request);
37	    }
38	
39	    private static void require(List<String> missing, String field, String value) {
40	        if (value == null || value.isBlank()) {
41	            missing.add(field);
42	        }
43	    }
44	}
