7	/**
8	 * Normalizes the create-owner telephone to E.164 form (see {@link TelephoneNormalizer}).
9	 * Runs after {@link ValidateOwnerFields} (so the field is known to be present) and
10	 * before {@link BuildOwner}, mutating the published {@link OwnerFieldsDto} in place so
11	 * the owner is built and stored with the E.164 value. A number that cannot form valid
12	 * E.164 is rejected as a 400 via {@link InvalidTelephoneException}.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
17	        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
18	        if (e164 == null) {
19	            throw new InvalidTelephoneException(request.getTelephone());
20	        }
21	        request.setTelephone(e164);
22	    }
23	}
