8	
9	/**
10	 * Rejects a create request once the maximum number of owners has already been registered
11	 * on the effective registration date resolved by {@link ResolveRegistrationDate} — the
12	 * adjusted business day this create will land on, not necessarily the server's today. Runs
13	 * before {@link BuildOwner}, so an over-limit day is a 429 via
14	 * {@link DailyLimitExceededException} before any owner is built or saved.
15	 */
16	public class EnsureDailyLimit {
17	
18	    /** Maximum owners that may be registered on a single day; the next create is rejected. */
19	    static final long MAX_OWNERS_PER_DAY = 100;
20	
21	    public void service(@Val LocalDate registrationDate, OwnerRepository ownerRepository)
22	            throws DailyLimitExceededException {
23	        if (DailyRegistrations.countOn(ownerRepository, registrationDate) >= MAX_OWNERS_PER_DAY) {
24	            throw new DailyLimitExceededException(MAX_OWNERS_PER_DAY);
25	        }
26	    }
27	}
