4	
5	/**
6	 * Shared telephone normalization for the owner pipelines: convert a raw telephone to
7	 * E.164 form. Spaces, dashes and brackets are stripped; a number that already carries
8	 * a leading {@code '+'} keeps its country code, otherwise Australian country code
9	 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
10	 * national digits. The result is a {@code '+'} followed by 8 to 15 digits.
11	 *
12	 * <p>The national-number length must also match the country code: {@code '+61'}
13	 * (Australia) requires 9 national digits and {@code '+1'} (NANP) requires 10. A number
14	 * whose national part is the wrong length for its country is not valid E.164 here.
15	 *
16	 * <p>Used by {@link NormalizeOwnerTelephone}, which rejects a number that cannot form
17	 * valid E.164 and stores the normalized value, so every owner's telephone is canonical
18	 * before it becomes part of the owner's identity key.
19	 */
20	final class TelephoneNormalizer {
21	
22	    private TelephoneNormalizer() {
23	    }
24	
25	    /**
26	     * @return the E.164 representation of {@code telephone}, or {@code null} when it
27	     *         cannot form a valid E.164 number.
28	     */
29	    static String toE164(String telephone) {
30	        if (telephone == null) {
31	            return null;
32	        }
33	        String cleaned = telephone.replaceAll("[\\s()-]", "");
34	        String digits;
35	        if (cleaned.startsWith("+")) {
36	            digits = cleaned.substring(1);
37	        }
38	        else {
39	            if (cleaned.startsWith("0")) {
40	                cleaned = cleaned.substring(1);
41	            }
42	            digits = "61" + cleaned;
43	        }
44	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
45	            return null;
46	        }
47	        return "+" + digits;
48	    }
49	
50	    /**
51	     * @return whether the national digits following a recognised country code have the
52	     *         length that code requires. Unrecognised country codes are left to the
53	     *         general 8-to-15-digit E.164 shape check.
54	     */
55	    private static boolean hasValidNationalLength(String digits) {
56	        String code = Telephone.countryCode(digits);
57	        if (code == null) {
58	            return true;
59	        }
60	        return digits.length() - code.length() == Telephone.nationalLength(code);
61	    }
62	}
