3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Shared address normalization for the owner pipelines: trim, collapse internal
8	 * whitespace, upper-case, and expand common street-type abbreviations
9	 * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}, matched whole-word).
10	 *
11	 * <p>Used by {@link ValidateOwnerFields} so a created owner is stored and returned
12	 * with the canonical address (and the required-field check rejects an address that is
13	 * blank once normalized). The transform is idempotent, so re-normalizing an
14	 * already-normalized address is a no-op.
15	 */
16	final class AddressNormalizer {
17	
18	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
19	
20	    private AddressNormalizer() {
21	    }
22	
23	    /**
24	     * @return the canonical form of {@code address}, or {@code ""} when it is null or
25	     *         blank (so callers can treat a blank-after-normalization address uniformly).
26	     */
27	    static String normalize(String address) {
28	        if (address == null) {
29	            return "";
30	        }
31	        String collapsed = WHITESPACE.matcher(address.strip()).replaceAll(" ").toUpperCase(Locale.ROOT);
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        StringBuilder normalized = new StringBuilder(collapsed.length());
37	        for (String token : tokens) {
38	            if (normalized.length() > 0) {
39	                normalized.append(' ');
40	            }
41	            normalized.append(expand(token));
42	        }
43	        return normalized.toString();
44	    }
45	
46	    /** Expand a single street-type abbreviation to its full word, else leave it unchanged. */
47	    private static String expand(String token) {
48	        switch (token) {
49	            case "ST":
50	                return "STREET";
51	            case "RD":
52	                return "ROAD";
53	            case "AVE":
54	                return "AVENUE";
55	            default:
56	                return token;
57	        }
58	    }
59	}
