13	
14	    /**
15	     * A single, unquoted local part, an {@code @}, then a dotted domain with a
16	     * multi-character final label. Deliberately conservative: it rejects an address
17	     * with no {@code @} or no domain while accepting ordinary mailbox addresses.
18	     */
19	    private static final Pattern EMAIL = Pattern.compile(
20	            "^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
21	
22	    private EmailNormalizer() {
23	    }
24	
25	    static boolean isValid(String email) {
26	        return email != null && EMAIL.matcher(email.trim()).matches();
27	    }
28	
29	    static String normalize(String email) {
30	        return email.trim().toLowerCase(Locale.ROOT);
31	    }
32	
33	    /**
34	     * The lower-cased domain part (after the last {@code @}), or {@code null} when the
35	     * address has no domain. Kept here so domain-based policies parse the address the
36	     * same way the validator does.
37	     */
38	    static String domainOf(String email) {
39	        if (email == null) {
40	            return null;
41	        }
42	        int at = email.lastIndexOf('@');
43	        return at < 0 ? null : email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
44	    }
