5	/**
6	 * Fixed inclusive 4-digit postcode ranges keyed by an owner's region (as derived by
7	 * {@link CityRegion}). The table is pinned; a region with no entry — including
8	 * {@link CityRegion#UNKNOWN} — accepts any well-formed 4-digit postcode.
9	 */
10	public final class PostcodeRange {
11	
12	    /** Region to its inclusive {@code {low, high}} 4-digit postcode range. */
13	    private static final Map<String, int[]> REGION_RANGE = Map.of(
14	        "NSW", new int[] {2000, 2099},
15	        "VIC", new int[] {3000, 3099},
16	        "QLD", new int[] {4000, 4099});
17	
18	    private PostcodeRange() {
19	    }
20	
21	    /**
22	     * Whether the given 4-digit {@code postcode} is valid for {@code city}. A city whose
23	     * region has no known range (the permissive default) accepts any postcode.
24	     *
25	     * @param city     the owner's city, mapped to a region via {@link CityRegion}
26	     * @param postcode a well-formed 4-digit postcode string
27	     * @return {@code true} when the postcode falls in the city's region range, or the
28	     *         region has no known range
29	     */
30	    public static boolean isValidForCity(String city, String postcode) {
31	        int[] range = REGION_RANGE.get(CityRegion.localityOf(city));
32	        if (range == null) {
33	            return true;
34	        }
35	        int value = Integer.parseInt(postcode);
36	        return value >= range[0] && value <= range[1];
37	    }
38	
39	    /**
