4	
5	/**
6	 * The owner's customer-code identity, formatted {@code <REGION>-<HASH8>} where REGION is
7	 * the owner's region (see {@link OwnerRegion}) and HASH8 is the first 8 upper-case hex
8	 * characters of SHA-256 over the normalized telephone concatenated with the last name
9	 * (e.g. {@code NSW-1A2B3C4D}). This is the single source of an owner's identity: the
10	 * membership number, its check digit and the audit record are all built from it, and the
11	 * locality is the REGION read back out of it.
12	 */
13	public final class CustomerCode {
14	
15	    /** Separator between the REGION and HASH8 segments. */
16	    private static final String SEPARATOR = "-";
17	
18	    /** Number of leading hex characters of the digest kept as the HASH8 segment. */
19	    private static final int HASH_LENGTH = 8;
20	
21	    private CustomerCode() {
22	    }
23	
24	    /**
25	     * The {@code <REGION>-<HASH8>} customer code for the given region and identity inputs.
26	     *
27	     * @param region    the owner's region, used verbatim as the REGION segment
28	     * @param telephone the owner's normalized (E.164) telephone
29	     * @param lastName  the owner's last name
30	     */
31	    public static String of(String region, String telephone, String lastName) {
32	        return region + SEPARATOR + hash8(telephone, lastName);
33	    }
34	
35	    /** The REGION segment of a customer code: everything before the first separator. */
36	    public static String regionOf(String customerCode) {
37	        int separator = customerCode.indexOf(SEPARATOR);
38	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
39	    }
40	
41	    /** First {@value #HASH_LENGTH} upper-case hex characters of SHA-256(telephone + lastName). */
42	    private static String hash8(String telephone, String lastName) {
43	        return Sha256.hex(telephone + lastName).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
